import * as Parchment from 'parchment';

const CORE_BLOT_NAMES = new Set<string>([
  'block',
  'break',
  'cursor',
  'inline',
  'scroll',
  'text',
]);

function createRegistryWithFormats(
  formats: string[] | null,
  sourceRegistry: Parchment.Registry,
  debug: { error: (message: string) => void },
): Parchment.Registry {
  // If formats is null or not provided, return a clone of the source registry
  // to maintain backwards compatibility.
  if (formats == null) {
    const registry = new Parchment.Registry();
    for (const [name, def] of Object.entries((sourceRegistry as any).types)) {
      // @ts-expect-error
      registry.register(def);
    }
    return registry;
  }

  const registry = new Parchment.Registry();
  const registered = new Set<string>();
  const queue = [...formats];

  while (queue.length > 0) {
    const name = queue.shift() as string;

    // Always include core blots
    if (CORE_BLOT_NAMES.has(name)) {
      if (!registered.has(name)) {
        const blot = (sourceRegistry as any).types[name];
        if (blot != null) {
          // @ts-expect-error
          registry.register(blot);
          registered.add(name);

          // Check for required container recursively
          if (blot.requiredContainer != null) {
            const reqName = blot.requiredContainer.blotName;
            if (!registered.has(reqName)) {
              queue.push(reqName);
            }
          }
        }
      }
      continue;
    }

    // Look up the format in source registry
    const blot = (sourceRegistry as any).types[name];
    if (blot == null) {
      debug.error(`Cannot find format: ${name}`);
      continue;
    }

    if (registered.has(name)) {
      continue;
    }

    // @ts-expect-error
    registry.register(blot);
    registered.add(name);

    // Check for required container recursively
    if (blot.requiredContainer != null) {
      const reqName = blot.requiredContainer.blotName;
      if (CORE_BLOT_NAMES.has(reqName)) {
        // Core blots are already handled, but register them if not yet
        if (!registered.has(reqName)) {
          const coreBlot = (sourceRegistry as any).types[reqName];
          if (coreBlot != null) {
            // @ts-expect-error
            registry.register(coreBlot);
            registered.add(reqName);
          }
        }
      } else {
        // Non-core required container: need to look it up and register it
        // Also follow its requiredContainer recursively
        if (!registered.has(reqName)) {
          const containerDef = (sourceRegistry as any).types[reqName];
          if (containerDef == null) {
            debug.error(`Cannot find required container: ${reqName}`);
          } else {
            // @ts-expect-error
            registry.register(containerDef);
            registered.add(reqName);

            // Recurse into its required container
            if (containerDef.requiredContainer != null) {
              const nestedReqName = containerDef.requiredContainer.blotName;
              // Avoid cycles: only add if not already registered or in queue for cycle detection
              if (registered.has(nestedReqName)) {
                // Cycle detected - the required container requires itself or a chain that leads back
                debug.error(`Cycle detected in required containers for ${name}`);
              } else {
                queue.push(nestedReqName);
              }
            }
          }
        }
      }
    }
  }

  return registry;
}

export default createRegistryWithFormats;
