  const config = { ...quillDefaults, ...themeDefaults, ...options };

  // Determine the registry to use:
  // 1. If registry option is explicitly provided, use it (takes precedence)
  // 2. If formats is an array, build a new registry from those formats
  // 3. Otherwise fall back to the default (global) registry
  let registry: Parchment.Registry;
  if ('registry' in config && config.registry != null) {
    registry = config.registry;
  } else if (Array.isArray(config.formats)) {
    registry = createRegistryWithFormats(config.formats, globalRegistry, debug);
  } else {
    registry = globalRegistry;
  }

  return {
    ...config,
    container,
    theme,
    modules: Object.entries(modules).reduce(
      (modulesWithDefaults, [name, value]) => {
        if (!value) return modulesWithDefaults;

        const moduleClass = Quill.import(`modules/${name}`);
        if (moduleClass == null) {
          debug.error(
            `Cannot load ${name} module. Are you sure you registered it?`,
          );
          return modulesWithDefaults;
        }
        return {
          ...modulesWithDefaults,
          // @ts-expect-error
          [name]: merge({}, moduleClass.DEFAULTS || {}, value),
        };
      },
      {},
    ),
    registry,
    bounds: resolveSelector(config.bounds),
  };
}

