import * as Parchment from 'parchment';

const CORE_BLOT_NAMES = new Set<string>([
  'block',
  'break',
  'cursor',
  'inline',
  'scroll',
  'text',
]);

function createRegistryWithFormats(
  formats: string[] | null,
  sourceRegistry: Parchment.Registry,
  debug: { error: (message: string) => void },
): Parchment.Registry {
  // If formats is null or not provided, return a clone of the source registry
  // to maintain backwards compatibility.
  if (formats == null) {
    const registry = new Parchment.Registry();
    // Copy all entries from source registry
    const sourceTypes = (sourceRegistry as any).types;
    for (const name of Object.keys(sourceTypes)) {
      registry.register(sourceTypes[name]);
    }
    return registry;
  }

  const registry = new Parchment.Registry();

  // 3-state tracking for cycle detection:
  // "resolving" = currently processing (in-progress stack for cycle detection)
  // "done" = fully processed, no need to revisit
  const resolving = new Set<string>();
  const done = new Set<string>();

  function registerBlot(name: string): boolean {
    // Core blots are always needed
    if (CORE_BLOT_NAMES.has(name)) {
      if (!done.has(name)) {
        const blot = (sourceRegistry as any).types[name];
        if (blot != null) {
          registry.register(blot);
          done.add(name);
        }
      }
      return true;
    }

    // Cycle detection: if we're already resolving this name, we have a cycle
    if (resolving.has(name)) {
      debug.error(`Cycle detected in required containers for ${name}`);
      return false;
    }

    // Already fully processed
    if (done.has(name)) {
      return true;
    }

    const blot = (sourceRegistry as any).types[name];
    if (blot == null) {
      debug.error(`Cannot find format: ${name}`);
      return false;
    }

    // Mark as in-progress before recursing into requiredContainer
    resolving.add(name);

    registry.register(blot);

    // Follow requiredContainer recursively
    if (blot.requiredContainer != null) {
      const reqName = blot.requiredContainer.blotName;
      if (!registerBlot(reqName)) {
        // cycle was reported inside
      }
    }

    resolving.delete(name);
    done.add(name);

    return true;
  }

  // Always register all core blots first
  for (const coreName of CORE_BLOT_NAMES) {
    const blot = (sourceRegistry as any).types[coreName];
    if (blot != null) {
      registry.register(blot);
      done.add(coreName);
    }
  }

  // Register requested formats and their required containers
  for (const name of formats) {
    registerBlot(name);
  }

  return registry;
}

export default createRegistryWithFormats;

