import '../../../src/quill.js';
import { describe, expect, test } from 'vitest';
import * as Parchment from 'parchment';
import Quill, { expandConfig, globalRegistry } from '../../../src/core/quill.js';
import createRegistryWithFormats from '../../../src/core/utils/createRegistryWithFormats.js';

describe('createRegistryWithFormats', () => {
  const createDebug = () => {
    const messages: string[] = [];
    return {
      error: (msg: string) => messages.push(msg),
      messages,
    };
  };

  test('null formats returns a copy of the source registry', () => {
    const debug = createDebug();
    const registry = createRegistryWithFormats(null, globalRegistry, debug);
    expect(debug.messages).toEqual([]);
    // The returned registry should be a different instance but contain same definitions
    expect(registry).not.toBe(globalRegistry);
  });

  test('core blots are always present', () => {
    const debug = createDebug();
    const registry = createRegistryWithFormats(['bold'], globalRegistry, debug);

    // Core blots should be present
    expect(registry.query('scroll', Parchment.Scope.ANY)).toBeTruthy();
    expect(registry.query('block', Parchment.Scope.ANY)).toBeTruthy();
    expect(registry.query('inline', Parchment.Scope.ANY)).toBeTruthy();
    expect(registry.query('text', Parchment.Scope.ANY)).toBeTruthy();
    expect(registry.query('break', Parchment.Scope.ANY)).toBeTruthy();
    expect(registry.query('cursor', Parchment.Scope.ANY)).toBeTruthy();

    // The requested format should be present
    expect(registry.query('bold', Parchment.Scope.ANY)).toBeTruthy();
    expect(debug.messages).toEqual([]);
  });

  test('unknown format names are skipped with error message', () => {
    const debug = createDebug();
    const registry = createRegistryWithFormats(['bold', 'nonexistent-format'], globalRegistry, debug);

    expect(registry.query('bold', Parchment.Scope.ANY)).toBeTruthy();
    expect(debug.messages.length).toBeGreaterThanOrEqual(1);
    expect(debug.messages[0]).toContain('nonexistent-format');
  });

  test('requiredContainer is followed recursively (list -> list-container)', () => {
    const debug = createDebug();
    const registry = createRegistryWithFormats(['list'], globalRegistry, debug);

    // list blot should be present
    expect(registry.query('list', Parchment.Scope.ANY)).toBeTruthy();
    // list-container should be auto-registered as requiredContainer
    expect(registry.query('list-container', Parchment.Scope.ANY)).toBeTruthy();
    expect(debug.messages).toEqual([]);
  });

  test('cycle detection in requiredContainer', () => {
    // Simulate a cycle by creating a registry where a blot requires itself
    const sourceRegistry = new Parchment.Registry();

    // Create a mock blot that requires itself
    const MockBlot: any = {
      blotName: 'mock',
      tagName: 'DIV',
      requiredContainer: null, // will be set to self
    };
    MockBlot.requiredContainer = MockBlot;

    sourceRegistry.register(MockBlot);

    const debug = createDebug();
    const registry = createRegistryWithFormats(['mock'], sourceRegistry, debug);

    expect(debug.messages.length).toBeGreaterThanOrEqual(1);
    expect(debug.messages[0]).toContain('Cycle detected');
  });

  test('code-block requires code-block-container', () => {
    const debug = createDebug();
    const registry = createRegistryWithFormats(['code-block'], globalRegistry, debug);

    expect(registry.query('code-block', Parchment.Scope.ANY)).toBeTruthy();
    expect(registry.query('code-block-container', Parchment.Scope.ANY)).toBeTruthy();
    expect(debug.messages).toEqual([]);
  });

  test('empty formats array creates registry with only core blots', () => {
    const debug = createDebug();
    const registry = createRegistryWithFormats([], globalRegistry, debug);

    // Core blots should be present
    expect(registry.query('scroll', Parchment.Scope.ANY)).toBeTruthy();
    expect(registry.query('block', Parchment.Scope.ANY)).toBeTruthy();
    // But no format blots
    expect(registry.query('bold', Parchment.Scope.ANY)).toBeFalsy();
    expect(debug.messages).toEqual([]);
  });

  test('multiple formats are all included', () => {
    const debug = createDebug();
    const registry = createRegistryWithFormats(['bold', 'italic', 'strike'], globalRegistry, debug);

    expect(registry.query('bold', Parchment.Scope.ANY)).toBeTruthy();
    expect(registry.query('italic', Parchment.Scope.ANY)).toBeTruthy();
    expect(registry.query('strike', Parchment.Scope.ANY)).toBeTruthy();
    expect(debug.messages).toEqual([]);
  });
});

describe('expandConfig with formats option', () => {
  const createContainer = (html = '') => {
    const container = document.createElement('div');
    container.innerHTML = html;
    document.body.appendChild(container);
    return container;
  };

  test('formats option filters the registry', () => {
    const container = createContainer();
    const config = expandConfig(container, { formats: ['bold', 'italic'] });

    // Should contain bold and italic
    expect(config.registry.query('bold', Parchment.Scope.ANY)).toBeTruthy();
    expect(config.registry.query('italic', Parchment.Scope.ANY)).toBeTruthy();
    // Core blots should always be present
    expect(config.registry.query('scroll', Parchment.Scope.ANY)).toBeTruthy();
    expect(config.registry.query('block', Parchment.Scope.ANY)).toBeTruthy();
    // Other formats should NOT be present
    expect(config.registry.query('list', Parchment.Scope.ANY)).toBeFalsy();
    expect(config.registry.query('header', Parchment.Scope.ANY)).toBeFalsy();

    document.body.removeChild(container);
  });

  test('formats null uses global registry', () => {
    const container = createContainer();
    const config = expandConfig(container, { formats: null });

    // Should have global registry content
    expect(config.registry.query('list', Parchment.Scope.ANY)).toBeTruthy();
    expect(config.registry.query('bold', Parchment.Scope.ANY)).toBeTruthy();

    document.body.removeChild(container);
  });

  test('registry option takes precedence over formats', () => {
    const container = createContainer();
    const customRegistry = new Parchment.Registry();
    const BoldClass: any = Quill.import('formats/bold');
    customRegistry.register(BoldClass);

    const config = expandConfig(container, { 
      formats: ['bold', 'italic'], 
      registry: customRegistry 
    });

    // Should use custom registry - only bold present
    expect(config.registry.query('bold', Parchment.Scope.ANY)).toBeTruthy();
    expect(config.registry.query('italic', Parchment.Scope.ANY)).toBeFalsy();

    document.body.removeChild(container);
  });

  test('no formats option uses global registry (backwards compat)', () => {
    const container = createContainer();
    const config = expandConfig(container, {});

    // Global registry should have all formats
    expect(config.registry.query('list', Parchment.Scope.ANY)).toBeTruthy();
    expect(config.registry.query('bold', Parchment.Scope.ANY)).toBeTruthy();

    document.body.removeChild(container);
  });
});

